import{_ as a,o as i,c as l,ag as t}from"./chunks/framework.BZohXCq9.js";const u=JSON.parse('{"title":"代码明明修了，板端为什么还在跑旧版本","description":"复盘配置、模型、CI、打包路径和运行时版本漂移，并建立从 source commit 到板端进程身份的发布追踪闭环","frontmatter":{"title":"代码明明修了，板端为什么还在跑旧版本","description":"复盘配置、模型、CI、打包路径和运行时版本漂移，并建立从 source commit 到板端进程身份的发布追踪闭环","tags":["Release","Debian Package","Traceability","CI/CD","问题复盘"],"date":"2026/07/20"},"headers":[],"relativePath":"linux/release-package-traceability.md","filePath":"linux/release-package-traceability.md","lastUpdated":1784519165000}'),o={name:"linux/release-package-traceability.md"};function c(r,e,d,p,s,n){return i(),l("div",null,[...e[0]||(e[0]=[t('<h1 id="代码明明修了-板端为什么还在跑旧版本" tabindex="-1">代码明明修了，板端为什么还在跑旧版本 <a class="header-anchor" href="#代码明明修了-板端为什么还在跑旧版本" aria-label="Permalink to &quot;代码明明修了，板端为什么还在跑旧版本&quot;">​</a></h1><p>“源码已经改了”与“板端正在运行修复后的程序”之间，隔着构建、打包、上传、安装、服务重启和进程替换。任何一层发生漂移，日志看起来就像新版本，真实执行文件却仍然来自旧 release。</p><p>这次发布链排障里，真正的问题并不在算法代码，而在资产路径、包内容和版本身份没有形成闭环。</p><h2 id="现场-每一层单独看都像是对的" tabindex="-1">现场：每一层单独看都像是对的 <a class="header-anchor" href="#现场-每一层单独看都像是对的" aria-label="Permalink to &quot;现场：每一层单独看都像是对的&quot;">​</a></h2><p>源码里已经替换了配置和模型路径，CI 也能运行，服务安装后还是 active。但检查最终 package 和板端进程时，陆续发现：</p><ul><li>运行时读取的配置实际位于 <code>/etc</code>，打包脚本却只放进 install tree；</li><li>模型文件名改了，CI 或 health check 仍引用旧名称；</li><li>payload 脚本的默认路径依赖调用时 cwd；</li><li>宿主机只完成 staging，没有生成真实 <code>.deb</code>；</li><li>板端降级后，旧进程没有完全停止，仍然持有相机设备。</li></ul><p>这类问题最难的地方是：每个阶段都可能给出局部成功。</p><h2 id="第一个根因-运行时路径与打包路径不是一回事" tabindex="-1">第一个根因：运行时路径与打包路径不是一回事 <a class="header-anchor" href="#第一个根因-运行时路径与打包路径不是一回事" aria-label="Permalink to &quot;第一个根因：运行时路径与打包路径不是一回事&quot;">​</a></h2><p>构建系统把默认配置安装到 <code>share/...</code>，不代表运行时就从那里读取。源码若固定读取 <code>/etc/camera.json</code>，factory package 必须显式把文件 stage 到 package root 的 <code>/etc</code>。</p><p>排查时不能从打包脚本猜运行时路径，应该从当前源码的 open/read 入口反查权威位置，再检查最终包内容。</p><h2 id="第二个根因-模型改名没有全链更新" tabindex="-1">第二个根因：模型改名没有全链更新 <a class="header-anchor" href="#第二个根因-模型改名没有全链更新" aria-label="Permalink to &quot;第二个根因：模型改名没有全链更新&quot;">​</a></h2><p>运行时资产路径通常同时出现在：</p><ul><li>service 或 launch 默认值；</li><li>payload 脚本；</li><li>CI 检查；</li><li>health check；</li><li>文档与示例命令。</li></ul><p>只替换源码中的模型名，会让 package、CI 和 runtime 各自持有不同答案。正确做法是把它们当成一份 release contract 一起搜索、修改和测试，并删除无意保留的 legacy fallback。</p><h2 id="第三个根因-脚本依赖当前目录" tabindex="-1">第三个根因：脚本依赖当前目录 <a class="header-anchor" href="#第三个根因-脚本依赖当前目录" aria-label="Permalink to &quot;第三个根因：脚本依赖当前目录&quot;">​</a></h2><p>脚本在 repo root 执行时正常，从 CI 或其他目录调用就找不到默认模型。这说明资源路径是相对 shell cwd，而不是相对脚本或仓库根目录。</p><p>修复后的原则是：先稳定解析 <code>repo_root</code>，再构造默认资源路径。用户显式传入的路径可以覆盖默认值，但默认行为不能依赖“大家刚好都从同一目录运行”。</p><h2 id="第四个根因-staging-不是-package-证据" tabindex="-1">第四个根因：Staging 不是 Package 证据 <a class="header-anchor" href="#第四个根因-staging-不是-package-证据" aria-label="Permalink to &quot;第四个根因：Staging 不是 Package 证据&quot;">​</a></h2><p>宿主机缺少 <code>dpkg-deb</code> 时，脚本可以把文件摆进临时 package tree，让目录检查全部通过，却没有生成真正可安装的包。</p><p>最终验证必须回到可信容器或目标架构构建环境：真实生成 <code>.deb</code>，列出包内容，安装到干净环境，并检查 post-install/service 行为。目录看起来正确，只能算中间证据。</p><h2 id="建立-source-commit-追踪" tabindex="-1">建立 Source Commit 追踪 <a class="header-anchor" href="#建立-source-commit-追踪" aria-label="Permalink to &quot;建立 Source Commit 追踪&quot;">​</a></h2><p>每个 production package 应携带：</p><ul><li>人可读的 app version；</li><li>完整 <code>source_commit</code>；</li><li>构建时间和目标架构；</li><li>关键资产版本或 hash；</li><li>构建 profile。</li></ul><p>版本可以类似：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>prod-YYYYmmdd-HHMMSS-g&lt;shortsha&gt;</span></span></code></pre></div><p>同时在运行时版本文件中保存完整 commit。这样 deb 文件名、板端状态接口和源码提交可以互相核对，而不是依赖 CI job 名或聊天记录。</p><h2 id="板端验收不能停在安装成功" tabindex="-1">板端验收不能停在安装成功 <a class="header-anchor" href="#板端验收不能停在安装成功" aria-label="Permalink to &quot;板端验收不能停在安装成功&quot;">​</a></h2><p>部署后按以下顺序确认：</p><ol><li>包管理器显示目标版本已安装；</li><li>运行时版本文件中的 <code>source_commit</code> 正确；</li><li>systemd 的 <code>MainPID</code> 已变化；</li><li><code>/proc/&lt;pid&gt;/exe</code> 指向目标 release；</li><li>旧进程与旧 container 已停止；</li><li>设备没有被旧 owner 占用；</li><li>topic、rate、socket 和 health 输出符合新版本合同。</li></ol><p>一次 A/B 测量中，版本切换后旧相机进程仍然存活，导致设备占用和基线异常。这个问题说明，package version 对了也不能代替进程身份验证。</p><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>发布可追踪性不是在版本页面多显示一个 commit id，而是把源码、资产、package、安装状态和真实进程连成一条证据链。</p><p>当板端行为与预期不一致时，第一步不该继续改代码，而应该先证明正在运行的到底是哪一份代码、哪一套配置和哪个模型。</p>',33)])])}const m=a(o,[["render",c]]);export{u as __pageData,m as default};
